const fs=require("fs"),p=require("path"),cp=require("child_process");
const git=(a)=>cp.execFileSync("git",a,{encoding:"utf8"});
const tracked=git(["diff","--name-only"]).trim().split("\n").filter(Boolean);
const untracked=git(["ls-files","--others","--exclude-standard"]).trim().split("\n").filter(Boolean);
const files=[...new Set([...tracked,...untracked])];
const badLinks=[],baselineBroken=[],fences=[],secrets=[];
const keyRules=[/sk-[A-Za-z0-9_-]{24,}/g,/gh[pousr]_[A-Za-z0-9]{30,}/g,/github_pat_[A-Za-z0-9_]{30,}/g,/-----BEGIN (?:RSA |EC |OPENSSH )?PRIVATE KEY-----/g,/AKIA[A-Z0-9]{16}/g];
for(const file of files){
 const s=fs.readFileSync(file,"utf8");let old="";if(tracked.includes(file))old=git(["show","HEAD:"+file]);
 for(const rule of keyRules){rule.lastIndex=0;const hit=rule.test(s);rule.lastIndex=0;if(hit&&!rule.test(old))secrets.push({file,rule:rule.source});}
 if(!file.endsWith(".md"))continue;
 const outside=s.replace(/\x60{3}[\s\S]*?\x60{3}/g,"");
 for(const m of outside.matchAll(/\[[^\]]*\]\(([^)]+)\)/g)){
  let target=m[1].replace(/^<|>$/g,"").split("#")[0];
  if(!target||/^[A-Za-z]+:/.test(target))continue;
  target=decodeURIComponent(target);
  if(!fs.existsSync(p.resolve(p.dirname(file),target))){
   const item={file,target};if(old.includes(m[0]))baselineBroken.push(item);else badLinks.push(item);
  }
 }
 if((s.match(/^\x60{3}/gm)||[]).length%2)fences.push(file);
}
const lesson=fs.readFileSync("docs/fastapi/day83-human-approval-interrupt-and-escalation-boundaries.md","utf8");
const headings=[...lesson.matchAll(/^## (\d+)\. (.+)$/gm)].map(m=>[Number(m[1]),m[2]]);
const names=["Lesson Metadata","Learning Objectives","Why This Matters","Roadmap Position","Lesson Map","Core Mental Model","Main Concepts","Common Misconceptions","Engineering Trade-offs","Hands-on Exercises","Relevant Framework Connections","AI Backend Connections","English Interview","Mental Model Summary","Today's Takeaway","Before Next Lesson Checklist"];
const templateOK=headings.length===16&&headings.every((h,i)=>h[0]===i+1&&h[1]===names[i]);
const protectedFiles=["prompts/master-prompt.md","prompts/teaching-session-prompt.md","LESSON_TEMPLATE_v2.md"];
const protectedUnchanged=protectedFiles.every(f=>git(["show","HEAD:"+f])===fs.readFileSync(f,"utf8"));
const currentSurfaces=["AGENTS.md","README.md","PROJECT_STATUS.md","TASKS.md"];
const staleCurrent=currentSurfaces.filter(f=>/Day83 is next|Day82 is the current\/next-up|Day83[^\n]*Planned/.test(fs.readFileSync(f,"utf8")));
const summary={modified:tracked.length,added:untracked.length,files,newBrokenLinks:badLinks,preexistingBrokenLinks:baselineBroken,unbalancedFences:fences,credentialPatternFindings:secrets,template16Sections:templateOK,protectedUnchanged,staleCurrent};
console.log(JSON.stringify(summary,null,2));if(badLinks.length||fences.length||secrets.length||!templateOK||!protectedUnchanged||staleCurrent.length)process.exitCode=1;
